(function(){
  'use strict';
  function hexToBytes(s){
    var t=String(s||'').replace(/0x/gi,' ').replace(/[^0-9a-fA-F]/g,'');
    if(t.length%2) t=t.slice(0,-1);
    var o=new Uint8Array(t.length/2);
    for(var i=0;i<o.length;i++) o[i]=parseInt(t.substr(i*2,2),16);
    return o;
  }
  function hx(n,w){ var s=(n>>>0).toString(16).toUpperCase(); while(s.length<(w||8)) s='0'+s; return '0x'+s; }
  function u8(b,p){ return b[p]; }
  function u16(b,p){ return b[p] | (b[p+1]<<8); }
  function u32(b,p){ return (b[p] | (b[p+1]<<8) | (b[p+2]<<16) | (b[p+3]<<24))>>>0; }
  function u64(b,p){ var lo=u32(b,p), hi=u32(b,p+4); return hi*4294967296+lo; }
  function hex64(b,p){ var lo=u32(b,p), hi=u32(b,p+4);
    var s=hi.toString(16).toUpperCase(); while(s.length<8) s='0'+s;
    var t=lo.toString(16).toUpperCase(); while(t.length<8) t='0'+t;
    return '0x'+s+t; }

  var MACHINE={0:'UNKNOWN',0x14c:'i386',0x1c0:'ARM',0x1c4:'ARMNT (Thumb-2)',0xaa64:'ARM64',
               0x8664:'x64 (AMD64)',0x200:'IA64',0x5032:'RISCV32',0x5064:'RISCV64',0x6264:'LOONGARCH64'};
  var SUBSYS={0:'UNKNOWN',1:'NATIVE',2:'WINDOWS_GUI',3:'WINDOWS_CUI',5:'OS2_CUI',7:'POSIX_CUI',
              9:'WINDOWS_CE_GUI',10:'EFI_APPLICATION',11:'EFI_BOOT_SERVICE_DRIVER',
              12:'EFI_RUNTIME_DRIVER',13:'EFI_ROM',14:'XBOX',16:'WINDOWS_BOOT_APPLICATION'};
  var CHARS=[[0x0001,'RELOCS_STRIPPED'],[0x0002,'EXECUTABLE_IMAGE'],[0x0004,'LINE_NUMS_STRIPPED'],
             [0x0008,'LOCAL_SYMS_STRIPPED'],[0x0020,'LARGE_ADDRESS_AWARE'],[0x0080,'BYTES_REVERSED_LO'],
             [0x0100,'32BIT_MACHINE'],[0x0200,'DEBUG_STRIPPED'],[0x0400,'REMOVABLE_RUN_FROM_SWAP'],
             [0x0800,'NET_RUN_FROM_SWAP'],[0x1000,'SYSTEM'],[0x2000,'DLL'],[0x4000,'UP_SYSTEM_ONLY']];
  var DLLC=[[0x0020,'HIGH_ENTROPY_VA'],[0x0040,'DYNAMIC_BASE (ASLR)'],[0x0080,'FORCE_INTEGRITY'],
            [0x0100,'NX_COMPAT (DEP)'],[0x0200,'NO_ISOLATION'],[0x0400,'NO_SEH'],[0x0800,'NO_BIND'],
            [0x1000,'APPCONTAINER'],[0x2000,'WDM_DRIVER'],[0x4000,'GUARD_CF'],[0x8000,'TERMINAL_SERVER_AWARE']];
  var SECF=[[0x00000020,'CODE'],[0x00000040,'INITIALIZED_DATA'],[0x00000080,'UNINITIALIZED_DATA'],
            [0x02000000,'DISCARDABLE'],[0x04000000,'NOT_CACHED'],[0x08000000,'NOT_PAGED'],
            [0x10000000,'SHARED'],[0x20000000,'EXECUTE'],[0x40000000,'READ'],[0x80000000,'WRITE']];
  var DIRNAMES=['Export','Import','Resource','Exception','Certificate','BaseReloc','Debug','Architecture',
                'GlobalPtr','TLS','LoadConfig','BoundImport','IAT','DelayImport','CLR Runtime','Reserved'];

  function flags(table, v){
    var o=[];
    for(var i=0;i<table.length;i++){ if((v & table[i][0])===table[i][0] && table[i][0]!==0) o.push(table[i][1]); }
    return o;
  }
  function stamp(t){
    if(!t) return '0 (未设置)';
    var d=new Date(t*1000);
    if(t>4102444800 || isNaN(d.getTime())) return String(t)+' (非时间戳，可能是 Reproducible Build 哈希)';
    return String(t)+'  '+d.toISOString().replace('.000','');
  }
  function secName(b,p){
    var s='';
    for(var i=0;i<8;i++){ var c=b[p+i]; if(!c) break; s+=String.fromCharCode(c); }
    return s;
  }

  function parse(input){
    var b = (input instanceof Uint8Array) ? input : hexToBytes(input);
    var warns=[];
    if(!b.length) return {value:null, error:'输入为空'};
    if(b.length<64) return {value:null, error:'文件过短（'+b.length+' 字节），不足 DOS 头 64 字节'};
    if(!(b[0]===0x4D && b[1]===0x5A)) return {value:null, error:'缺少 DOS 魔数 MZ（当前 0x'+
      ((b[0]<16?'0':'')+b[0].toString(16))+((b[1]<16?'0':'')+b[1].toString(16))+'）'};
    var lfanew = u32(b, 0x3C);
    if(lfanew+24 > b.length) return {value:null, error:'e_lfanew='+hx(lfanew)+' 指向文件外（文件 '+b.length+' 字节）'};
    if(!(b[lfanew]===0x50 && b[lfanew+1]===0x45 && b[lfanew+2]===0 && b[lfanew+3]===0))
      return {value:null, error:'偏移 '+hx(lfanew)+' 处不是 PE\\0\\0 签名'};

    var c = lfanew+4;
    var coff = {
      machine: u16(b,c), machineName: MACHINE[u16(b,c)] || ('未知 '+hx(u16(b,c),4)),
      sections: u16(b,c+2), timeDateStamp: u32(b,c+4),
      symbolPtr: u32(b,c+8), symbols: u32(b,c+12),
      optSize: u16(b,c+16), characteristics: u16(b,c+18)
    };
    coff.time = stamp(coff.timeDateStamp);
    coff.flags = flags(CHARS, coff.characteristics);
    if(coff.symbols) warns.push('存在 COFF 符号表（'+coff.symbols+' 项），现代链接器通常不再输出');

    var o = c+20, opt=null;
    if(coff.optSize===0){
      warns.push('SizeOfOptionalHeader=0，这是目标文件（.obj）而非可执行映像');
    } else {
      if(o+2>b.length) return {value:null, error:'Optional 头被截断'};
      var magic=u16(b,o), pe32plus = magic===0x20B;
      if(magic!==0x10B && magic!==0x20B && magic!==0x107)
        return {value:null, error:'未知 Optional 头魔数 '+hx(magic,4)};
      var need = pe32plus?112:112;
      if(o+need>b.length) return {value:null, error:'Optional 头被截断（需 '+need+' 字节）'};
      opt = {
        magic: magic, kind: magic===0x20B?'PE32+':(magic===0x10B?'PE32':'ROM'),
        linker: u8(b,o+2)+'.'+u8(b,o+3),
        sizeOfCode: u32(b,o+4), sizeOfInitData: u32(b,o+8), sizeOfUninitData: u32(b,o+12),
        entryPoint: u32(b,o+16), baseOfCode: u32(b,o+20)
      };
      var q = pe32plus ? o+24 : o+28;
      if(!pe32plus) opt.baseOfData = u32(b,o+24);
      opt.imageBase = pe32plus ? hex64(b,q) : hx(u32(b,q));
      q += pe32plus?8:4;
      opt.sectionAlignment = u32(b,q); opt.fileAlignment = u32(b,q+4);
      opt.osVersion = u16(b,q+8)+'.'+u16(b,q+10);
      opt.imageVersion = u16(b,q+12)+'.'+u16(b,q+14);
      opt.subsystemVersion = u16(b,q+16)+'.'+u16(b,q+18);
      opt.sizeOfImage = u32(b,q+24); opt.sizeOfHeaders = u32(b,q+28);
      opt.checkSum = u32(b,q+32);
      opt.subsystem = u16(b,q+36); opt.subsystemName = SUBSYS[opt.subsystem] || ('未知 '+opt.subsystem);
      opt.dllCharacteristics = u16(b,q+38);
      opt.dllFlags = flags(DLLC, opt.dllCharacteristics);
      var st = q+40;
      if(pe32plus){ opt.stackReserve=u64(b,st); opt.stackCommit=u64(b,st+8);
                    opt.heapReserve=u64(b,st+16); opt.heapCommit=u64(b,st+24); st+=32; }
      else { opt.stackReserve=u32(b,st); opt.stackCommit=u32(b,st+4);
             opt.heapReserve=u32(b,st+8); opt.heapCommit=u32(b,st+12); st+=16; }
      opt.loaderFlags = u32(b,st);
      opt.numberOfRvaAndSizes = u32(b,st+4);
      opt.dirs=[];
      var dp = st+8;
      for(var i=0;i<opt.numberOfRvaAndSizes && i<16; i++){
        if(dp+8>b.length) break;
        var rva=u32(b,dp), sz=u32(b,dp+4); dp+=8;
        if(rva||sz) opt.dirs.push({index:i, name:DIRNAMES[i]||('#'+i), rva:hx(rva), size:sz});
      }
      if(opt.fileAlignment && (opt.fileAlignment & (opt.fileAlignment-1)))
        warns.push('FileAlignment '+opt.fileAlignment+' 不是 2 的幂，违反 PE 规范');
      if(opt.sectionAlignment && opt.fileAlignment && opt.sectionAlignment < opt.fileAlignment)
        warns.push('SectionAlignment 小于 FileAlignment，加载器会拒绝');
      if(opt.dllFlags.indexOf('NX_COMPAT (DEP)')<0) warns.push('未开启 NX_COMPAT（DEP），缺少数据执行保护');
      if(opt.dllFlags.indexOf('DYNAMIC_BASE (ASLR)')<0) warns.push('未开启 DYNAMIC_BASE（ASLR），地址可预测');
    }

    var sp = lfanew+4+20+coff.optSize, sections=[];
    for(var k=0;k<coff.sections;k++){
      if(sp+40>b.length){ warns.push('节表被截断：期望 '+coff.sections+' 节，只读到 '+k+' 节'); break; }
      var s={
        name: secName(b,sp), virtualSize:u32(b,sp+8), virtualAddress:u32(b,sp+12),
        rawSize:u32(b,sp+16), rawPtr:u32(b,sp+20), relocs:u16(b,sp+32),
        characteristics:u32(b,sp+36)
      };
      s.flags = flags(SECF, s.characteristics);
      s.rvaHex = hx(s.virtualAddress);
      if(s.flags.indexOf('WRITE')>=0 && s.flags.indexOf('EXECUTE')>=0)
        warns.push('节 '+s.name+' 同时可写可执行（W^X 违规）');
      if(s.rawPtr && s.rawSize && s.rawPtr+s.rawSize > b.length)
        s.truncated = true;
      sections.push(s);
      sp += 40;
    }
    var isDll = coff.flags.indexOf('DLL')>=0;
    return {value:{lfanew:lfanew, lfanewHex:hx(lfanew), coff:coff, opt:opt, sections:sections,
                   warnings:warns, fileSize:b.length,
                   kind: coff.optSize===0?'COFF 目标文件':(isDll?'DLL':'EXE')}, error:''};
  }

  var API={parse:parse, hexToBytes:hexToBytes, MACHINE:MACHINE, SUBSYS:SUBSYS, flags:flags,
           CHARS:CHARS, DLLC:DLLC, SECF:SECF, stamp:stamp};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__PeForge__=API;
})();
